function r(){gsap.utils.toArray(".section--hero").forEach(e=>{let o=e.querySelector(".wp-block-cover__image-background");o&&gsap.effects.parallax(o,{yFrom:0,yTo:5,scaleFrom:1,scaleTo:1.04,parent:e,start:"top top"})})}function s(){gsap.utils.toArray(".section--hero-2").forEach(e=>{let o=e.querySelector(".wp-block-cover"),l=e.querySelector(".wp-block-cover__image-background");o&&l&&gsap.effects.parallax(l,{parent:o,yFrom:0,scaleFrom:1,start:"top top"})})}function c(){gsap.utils.toArray(".section--hero-3").forEach(e=>{let o=e.querySelector(".wp-block-cover__image-background");o&&gsap.effects.parallax(o,{yFrom:0,yTo:5,scaleFrom:1,scaleTo:1.04,parent:e,start:"top top"})})}function n(){gsap.utils.toArray(".section--mission").forEach(e=>{let o=e.querySelector(".wp-block-cover__image-background");o&&gsap.effects.parallax(o,{parent:e})})}function a(){gsap.utils.toArray(".section--contact").forEach(e=>{let o=e.querySelector(".wp-block-cover__image-background");o&&gsap.effects.parallax(o,{parent:e})})}function i(){gsap.utils.toArray(".section--features").forEach(e=>{let o=e.querySelectorAll(".featured-list__item");o?.length&&gsap.effects.fadeInUpBatch(o)})}function p(){if(!document.body.classList.contains("wp-singular"))return;let e=document.querySelector(".entry")?.querySelector(".wp-block-cover"),o=e?.querySelector(".wp-block-cover__image-background");o&&gsap.effects.parallax(o,{yFrom:0,yTo:5,scaleFrom:1,scaleTo:1.04,parent:e,start:"top top"})}window.addEventListener("load",()=>{r(),s(),c(),n(),a(),i(),p()});
